    copied = []
    for value in values:
        copied.append(_equivalence_affine_left_0_coerce(value))
    return tuple(copied)

def _equivalence_affine_left_0_support(values):
    support = []
    for offset, value in enumerate(_equivalence_affine_left_0_snapshot(values)):
        support.append((_equivalence_affine_left_0_coordinate(), offset, value))
    return tuple(support)

