    profile = []
    for coordinate, offset, value in _equivalence_affine_left_0_support(values):
        profile.append((coordinate, offset % 2, value))
    return tuple(profile)

def _equivalence_affine_left_0_marker(*values):
    return (0, len(values), len(_equivalence_affine_left_0_descent_profile(values)))

